export function thumbScrollTarget({scrollY,rowTop,rowHeight,headingTop,headerHeight,viewportHeight,anchorY}){const values=[scrollY,rowTop,rowHeight,headingTop,headerHeight,viewportHeight,anchorY];if(values.some(n=>!Number.isFinite(n))||rowHeight<=0||viewportHeight<=0)return null;const rowCenter=rowTop+rowHeight/2,minAnchor=headerHeight+24+(rowCenter-headingTop),maxAnchor=viewportHeight-80;if(minAnchor>maxAnchor)return null;const target=Math.max(minAnchor,Math.min(anchorY,maxAnchor));return{top:Math.max(0,scrollY+rowCenter-target),anchor:target,runway:Math.max(0,viewportHeight-target)}}
